load_dotenv()

def collect_cerebras_keys():
    keys = []
    for k, v in os.environ.items():
        if k.startswith("CEREBRAS_API_KEY_") and v:
            try:
                idx = int(k.split("_")[-1])
            except ValueError:
                idx = 0
            keys.append((idx, v))
    keys.sort(key=lambda x: x[0])
    return [v for _, v in keys]

EXA_API_KEY = os.getenv("EXA_API_KEY")
CEREBRAS_API_KEYS = collect_cerebras_keys()

if not EXA_API_KEY or not CEREBRAS_API_KEYS:
    print("CRITICAL ERROR: API keys are not set in Replit Secrets.")
    print("Please set EXA_API_KEY and at least one CEREBRAS_API_KEY_1.")
    raise SystemExit(1)

DATABASE_FILE = "jaide_dataset.db"
MAX_CONCURRENT_EXA_TASKS = 10

